// GH #732 (friction F.7): an interface method declares `fallible(E)`,
// and a call through the interface carries the error channel. This
// used to fail to parse: `expected ;, got Ident("fallible")`.
type E { kind: String = ""; }
interface Store {
    fn put(k: String) -> Int fallible(E);
}
locus Mem {
    fn put(k: String) -> Int fallible(E) { if k == "" { fail E { kind: "empty" }; } return 1; }
}
fn keep(s: Store, k: String) -> Int { return s.put(k) or 0; }
fn main() {
    let m = Mem { };
    println(m.put("a") or 0);

// GH #732: an interface method declares `fallible(E)`, and a call
// through the interface carries the error channel exactly as a
// direct call on a fallible method does — success, failure, and every
// `or` form. An infallible method satisfies a fallible interface
// method and always takes the success path.

type StoreError { kind: String = ""; }

interface Store {
    fn put(k: String) -> Int fallible(StoreError);
    fn name_of(k: String) -> String fallible(StoreError);
    fn check(k: String) fallible(StoreError);
}

// An interface `accept` / `release` keeps the interface's contract in
// every monomorph. `Store.put` is `fallible(StoreError)`; `Lenient`
// implements it infallibly, which satisfies it (GH #732), and the body
// the checker typed through the interface addresses the error with
// `or`. In `Lenient`'s monomorph the call is direct and always takes the
// success path; in `Strict`'s it is the fallible method, both paths live.
// Each `or` form, `raise` included, and the `release` body alike.

type StoreError { kind: String = ""; }

interface Store {
    fn put(k: String) -> Int fallible(StoreError);
    fn check(k: String) fallible(StoreError);
}

fn write_report(path: String, body: String) fallible(IoError) {
    std::io::fs::write_file(path, body) or raise;
}

fn load(primary: String, backup: String) -> String fallible(IoError) {
    return std::io::fs::read_file(primary)
        or (std::io::fs::read_file(backup) or raise);
}

// The log write is the one call here whose failure the demo reports
// rather than absorbs: the helper raises it, `main` turns it into the
// status the output branches on.
fn write_log(path: String, text: String) -> Int fallible(IoError) {
    std::io::fs::write_file(path, text) or raise;
    return 0;
}

